# Read-only access to dynamic DB credentials for one role
path "database/creds/payments-ro" {
  capabilities = ["read"]
}

# Allow the app to renew its own lease, nothing else
path "sys/leases/renew" {
  capabilities = ["update"]
}

# Explicit deny on the static admin area
path "secret/data/admin/*" {
  capabilities = ["deny"]
}

